const results = [];

// 1. Loop through all incoming email items
for (const item of $input.all()) {
  let rawSubject = item.json.text || "";

  // Function to capitalize first letter
  const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);

  // 2. Remove the "Subject: " prefix if it exists
  // This turns "Subject: Topic 1, Topic 2" into "Topic 1, Topic 2"
  let cleanSubject = rawSubject;

  // 3. Logic: If there is a comma, split and trim
  if (cleanSubject.includes(',')) {
    const splitTopics = cleanSubject.split(',');

    for (const topic of splitTopics) {
      const trimmedTopic = topic.trim();
      if (trimmedTopic !== "") {
        results.push({
          json: {
            TOPICS: capitalize(trimmedTopic),
          }
        });
      }
    }
  } 
  // 4. Logic: No comma found, just trim the single topic
  else {
    const singleTopic = cleanSubject.trim()
    results.push({
      json: {
        TOPICS: capitalize(singleTopic),
      }
    });
  }
}

return results;

// Get all rows from Google Sheets
const allRows = $input.all(); // Each row has .json
// Get all topics from the previous code node
const emails = $items('Extract Topics from Email');

const results = [];

let currentRowIndex = 0; // track where to start checking for blank rows

for (const email of emails) {
    const topic = email.json.TOPICS;

    // Find the next blank row
    let firstBlankRow = null;
    for (let i = currentRowIndex; i < allRows.length; i++) {
        const row = allRows[i].json;
        if (!row.TOPICS || row.TOPICS.trim() === "") {
            firstBlankRow = row.row_number; // use row_number from Google Sheets
            currentRowIndex = i + 1; // move to next row for the next topic
            break;
        }
    }

    if (firstBlankRow !== null) {
        results.push({
            json: {
                row_number: firstBlankRow,
                TOPICS: topic,

            }
        });
    }
}

// Output the array of items to update in Google Sheets
return results;

const item = $input.first().json;

// Function to safely turn data into bullet points
const formatToList = (data) => {
  if (Array.isArray(data)) {
    return data.join('</li><li>');
  } else if (typeof data === 'string') {
    return data.split(',').join('</li><li>');
  }
  return data;
};

return {
  appended_TOPICS: formatToList(item.appended_TOPICS),
  appended_row_number: formatToList
    (item.appended_row_number)
};

