const allRows = $input.all();
const results = [];

/* STEP 1: Find last row (from bottom) with TOPICS*/

let lastContentIndex = -1;

for (let i = allRows.length - 1; i >= 0; i--) {
  const topic = (allRows[i].json["TOPICS"] || "").toString().trim();
  if (topic !== "") {
    lastContentIndex = i;
    break;
  }
}

/* STEP 2: CHECK ABOVE lastContentIndex. TOPICS must NOT be empty*/
if (lastContentIndex >= 0) {
  for (let i = lastContentIndex - 1; i >= 0; i--) {
    const row = allRows[i].json;
    const topic = (row["TOPICS"] || "").toString().trim();

    if (topic === "") {
      results.push({
        json: {
          row_number: row.row_number
        }
      });
    }
  }

  /* STEP 3: CHECK BELOW lastContentIndex. TOPICS empty is OK, BUT no other data allowed*/
  for (let i = lastContentIndex + 1; i < allRows.length; i++) {
    const row = allRows[i].json;
    const topic = (row["TOPICS"] || "").toString().trim();

    if (topic === "") {
      const posted = (row["POSTED?"] || "").toString().trim();
      const date = (row["DATE"] || "").toString().trim();
      const time = (row["TIME"] || "").toString().trim();
      const refined = (row["REFINED"] || "").toString().toUpperCase().trim();

      const hasOtherData =
        posted !== "" ||
        date !== "" ||
        time !== "" ||
        (refined !== "" && refined !== "FALSE");

      if (hasOtherData) {
        results.push({
          json: {
            row_number: row.row_number
            }
        });
      }
    }
  }
}

/* STEP 4: No TOPICS anywhere (edge case)*/
if (lastContentIndex === -1) {
  for (let i = 0; i < allRows.length; i++) {
    const row = allRows[i].json;
    const topic = (row["TOPICS"] || "").toString().trim();

    if (topic === "") {
      const posted = (row["POSTED?"] || "").toString().trim();
      const date = (row["DATE"] || "").toString().trim();
      const time = (row["TIME"] || "").toString().trim();
      const refined = (row["REFINED"] || "").toString().toUpperCase().trim();

      const hasOtherData =
        posted !== "" ||
        date !== "" ||
        time !== "" ||
        (refined !== "" && refined !== "FALSE");

      if (hasOtherData) {
        results.push({
          json: {
            row_number: row.row_number
          }
        });
      }
    }
  }
}

/* FINAL OUTPUT*/
if (results.length === 0) {
  // No rows to delete
  return [{
    json: {
      hasRowsToDelete: false,
      lastContentRowNumber:
        lastContentIndex >= 0
          ? allRows[lastContentIndex].json.row_number
          : null
    }
  }];
}

// If Rows existattach flag to each row
return results.map(r => ({
  json: {
    ...r.json,
    hasRowsToDelete: true
  }
}));

const allRows = $items("Fetch All Sheet Rows");
const lastContentRowNumber = $json.lastContentRowNumber;

const unrefinedRows = [];

for (let i = 0; i < allRows.length; i++) {
  const row = allRows[i].json;
  if (row.row_number > lastContentRowNumber) break;

