    // Push each row as a separate item for n8n
    unrefinedRows.push({ json: row });
  }
}

// If no rows match, return a single item with a boolean flag
if (unrefinedRows.length === 0) {
  return [{ json: { hasUnrefinedRows: false } }];
}

// Otherwise, add the flag to each item
return unrefinedRows.map(item => ({
  json: {
    ...item.json,
    hasUnrefinedRows: true
  }
}));

